/// 2. OR-consistency: ∀s ∈ σ: ψ(s) = NORMAL ⟹ |{c ∈ children(s) ∩ σ}| ≤ 1 (at most one child active)
/// 3. AND-consistency: ∀s ∈ σ: ψ(s) = PARALLEL ∧ s ∈ σ ⟹ children(s) ⊆ σ (all children active)
/// 4. Basic leaves: ∀s ∈ σ: ψ(s) = BASIC ⟹ children(s) ∩ σ = ∅ (basic states have no active children)
///
/// SEMANTIC INVARIANTS \[H87, HN96\]:
/// - Consistency: isConsistent(σ) ≡ satisfies all well-formedness constraints
/// - Maximality: isMaximal(σ) ≡ cannot add more states without violating consistency
/// - Reachability: isReachable(σ) ≡ ∃ event sequence from initial configuration
///
/// HISTORY SEMANTICS \[UML 2.5, SCXML\]:
/// History tracking enables restoration of previous configurations when re-entering
/// composite states, supporting both shallow and deep history variants.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Configuration {
    /// Active state set: σ ⊆ S
    #[prost(message, repeated, tag="1")]
    pub states: ::prost::alloc::vec::Vec<StateRef>,
    /// History mechanism \[UML 2.5\] for configuration restoration
    ///
    /// H: Label → P(S) history mapping
    #[prost(map="string, message", tag="2")]
    pub history: ::std::collections::HashMap<::prost::alloc::string::String, Configuration>,
}
// TimeoutSpec, TriggerSpec, and BroadcastSpec removed - these are modern
// extensions not present in the core Harel formalism \[H87, HN96, vdB94\].
// The original papers use simpler event-driven semantics without complex
// temporal or broadcast mechanisms.

// ───────────────────────────── Runtime execution ──────────────────────────────

/// *
/// Machine represents a statechart instance with execution state.
///
/// OPERATIONAL SEMANTICS \[HN96, Section 4\]:
/// A machine M = (SC, σ, Γ) consists of:
/// - SC: statechart definition (static structure)
/// - σ: current configuration (active states)
/// - Γ: variable context (dynamic data)
///
/// EXECUTION MODEL \[HN96, Section 4.1\]:
/// Machine execution proceeds through discrete steps triggered by events,
/// maintaining the current configuration and context state.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Machine {
    /// Machine identifier
    #[prost(string, tag="1")]
    pub id: ::prost::alloc::string::String,
    /// Execution state (running/stopped)
    #[prost(enumeration="MachineState", tag="2")]
    pub state: i32,
    /// Variable context: Γ: Var → Val
    #[prost(message, optional, tag="3")]
    pub context: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Static definition: SC
    #[prost(message, optional, tag="4")]
    pub statechart: ::core::option::Option<Statechart>,
    /// Current configuration: σ ∈ P(S)
    #[prost(message, optional, tag="5")]
    pub configuration: ::core::option::Option<Configuration>,
    /// Execution trace for analysis
    #[prost(message, repeated, tag="6")]
    pub step_history: ::prost::alloc::vec::Vec<Step>,
}
/// *
/// Step represents a single execution step in statechart operation.
///
/// STEP SEMANTICS \[HN96, Section 4.2\]:
/// A step σ →ᵉ σ' represents the transition from configuration σ to σ'
/// triggered by event set E', executing the enabled transitions.
///
/// STEP COMPONENTS \[HN96, Section 5\]:
/// Each step records:
/// - Input events that triggered the step
/// - Enabled and fired transitions
/// - Configuration change (σ → σ')
/// - Executed actions during the transition sequence
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Step {
    /// Triggering events: E' ⊆ E
    #[prost(message, repeated, tag="1")]
    pub events: ::prost::alloc::vec::Vec<Event>,
    /// Fired transitions: T' ⊆ δ
    #[prost(message, repeated, tag="2")]
    pub transitions: ::prost::alloc::vec::Vec<Transition>,
    /// Initial configuration: σ
    #[prost(message, optional, tag="3")]
    pub starting_configuration: ::core::option::Option<Configuration>,
    /// Final configuration: σ'
    #[prost(message, optional, tag="4")]
    pub resulting_configuration: ::core::option::Option<Configuration>,
    /// Updated context: Γ'
    #[prost(message, optional, tag="5")]
    pub context: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Execution trace information
    ///
    /// States entered: enter(σ')
    #[prost(string, repeated, tag="6")]
    pub states_entered: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// States exited: exit(σ)
    #[prost(string, repeated, tag="7")]
    pub states_exited: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// Actions fired: α*
    #[prost(message, repeated, tag="8")]
    pub actions_executed: ::prost::alloc::vec::Vec<Action>,
}
// ───────────────────────────── Enumerations ────────────────────────────────

/// *
/// StateType describes the fundamental classification of states in Harel's statechart formalism.
/// 
/// THEORETICAL FOUNDATION \[H87, Section 2.1\]:
/// The type function ψ: S → {BASIC, OR, AND} categorizes states by their decomposition:
/// - BASIC: atomic states with no substates (ψ(s) = BASIC ⟹ children(s) = ∅)
/// - OR: exclusive decomposition with XOR substate semantics (normal states)
/// - AND: concurrent decomposition with parallel substate semantics (orthogonal states)
///
/// SEMANTIC PROPERTIES \[HN96, Section 3\]:
/// - OR-states: ∀σ,s: ψ(s)=OR ⟹ |{c ∈ children(s) : c ∈ σ}| ≤ 1
/// - AND-states: ∀σ,s: ψ(s)=AND ∧ s ∈ σ ⟹ children(s) ⊆ σ
///
/// Note: This enum contains ONLY the core types from Harel's original formalism.
/// Modern extensions (history, pseudo-states) are intentionally excluded to maintain
/// theoretical purity and alignment with the cited academic papers.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum StateType {
    /// Undefined type (invalid in well-formed statecharts)
    Unspecified = 0,
    /// Core Harel state types \[H87, Section 2.1\]
    ///
    /// Atomic state: ψ(s) = BASIC ⟹ children(s) = ∅
    Basic = 1,
    /// OR-decomposition: exclusive substate semantics
    Or = 2,
    /// AND-decomposition: concurrent substate semantics
    And = 3,
}
impl StateType {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "STATE_TYPE_UNSPECIFIED",
            Self::Basic => "STATE_TYPE_BASIC",
            Self::Or => "STATE_TYPE_OR",
            Self::And => "STATE_TYPE_AND",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "STATE_TYPE_UNSPECIFIED" => Some(Self::Unspecified),
            "STATE_TYPE_BASIC" => Some(Self::Basic),
            "STATE_TYPE_OR" => Some(Self::Or),
            "STATE_TYPE_AND" => Some(Self::And),
            _ => None,
        }
    }
}
/// *
/// HistoryType distinguishes shallow vs deep history pseudostates.
///
/// FORMAL DEFINITION \[UML 2.5, Section 14.5.5\]:
/// History pseudostates enable restoration of prior configurations when
/// re-entering composite states, supporting two semantic variants:
/// - SHALLOW: Restores only the immediate child state of the composite
/// - DEEP: Restores the full nested configuration recursively
///
/// SEMANTIC PROPERTIES:
/// - H (shallow): restore(H, σ) = {s ∈ σ_prev | parent(s) = parent(H)}
/// - H* (deep): restore(H*, σ) = σ_prev ∩ descendants(parent(H*))
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum HistoryType {
    /// Default: treated as SHALLOW
    Unspecified = 0,
    /// H: restore immediate child only
    Shallow = 1,
    /// H*: restore full nested configuration
    Deep = 2,
}
impl HistoryType {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "HISTORY_TYPE_UNSPECIFIED",
            Self::Shallow => "HISTORY_TYPE_SHALLOW",
            Self::Deep => "HISTORY_TYPE_DEEP",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "HISTORY_TYPE_UNSPECIFIED" => Some(Self::Unspecified),
            "HISTORY_TYPE_SHALLOW" => Some(Self::Shallow),
            "HISTORY_TYPE_DEEP" => Some(Self::Deep),
            _ => None,
        }
    }
}
/// *
/// MachineState encodes the execution status of a statechart interpreter.
/// 
/// OPERATIONAL SEMANTICS \[HN96, Section 4\]:
/// Machine state tracks the interpreter's lifecycle, distinct from the 
/// statechart's logical configuration σ ∈ P(S).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum MachineState {
    /// Undefined interpreter state
    Unspecified = 0,
    /// Interpreter active, processing events
    Running = 1,
    /// Interpreter halted, no event processing
    Stopped = 2,
}
impl MachineState {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "MACHINE_STATE_UNSPECIFIED",
            Self::Running => "MACHINE_STATE_RUNNING",
            Self::Stopped => "MACHINE_STATE_STOPPED",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "MACHINE_STATE_UNSPECIFIED" => Some(Self::Unspecified),
            "MACHINE_STATE_RUNNING" => Some(Self::Running),
            "MACHINE_STATE_STOPPED" => Some(Self::Stopped),
            _ => None,
        }
    }
}
// ===========================================================================
// EXECUTION HISTORY, TRACING, AND STORAGE
//
// This file defines types for runtime execution tracing, checkpointing, and
// persistent storage of statechart execution history. These extensions enable
// debugging, auditing, replay, and recovery of statechart-based systems.
//
// THEORETICAL FOUNDATION:
// Execution traces formalize the operational semantics of statecharts as
// sequences of configurations connected by transitions \[HN96, Section 4\]:
//
//    Trace τ = σ₀ →^{e₁} σ₁ →^{e₂} σ₂ → ... →^{eₙ} σₙ
//
// where each step σᵢ →^{eᵢ₊₁} σᵢ₊₁ represents a transition triggered by
// event eᵢ₊₁ from configuration σᵢ to σᵢ₊₁.
//
// PRIMARY REFERENCES:
// \[H87\]   D. Harel, "Statecharts: A visual formalism for complex systems,"
//          Science of Computer Programming, vol. 8, no. 3, pp. 231–274, 1987.
//          DOI: 10.1016/0167-6423(87)90035-9
//
// \[HN96\]  D. Harel and A. Naamad, "The STATEMATE semantics of statecharts,"
//          ACM Trans. Softw. Eng. Methodol., vol. 5, no. 4, pp. 293–333, 1996.
//          DOI: 10.1145/235321.235322
//
// \[Lam78\] L. Lamport, "Time, clocks, and the ordering of events in a
//          distributed system," Commun. ACM, vol. 21, no. 7, pp. 558–565, 1978.
//          DOI: 10.1145/359545.359563
//
// DESIGN REFERENCE: docs/design/evolution-and-history.md
// ===========================================================================

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 1: TRANSITION LOGGING
// ═══════════════════════════════════════════════════════════════════════════

/// *
/// TransitionLogEntry records a single step in statechart execution.
///
/// FORMAL DEFINITION \[HN96, Section 4\]:
/// A log entry L = (t, seq, e, σ, σ', T, G, A, Γ, Γ') captures:
///    - t: timestamp of step execution
///    - seq: monotonic sequence number
///    - e: triggering event
///    - σ, σ': source and target configurations
///    - T: set of transitions that fired
///    - G: guard evaluation results
///    - A: actions executed
///    - Γ, Γ': context before and after
///
/// SEMANTIC INVARIANTS:
/// 1. seq(Lᵢ) < seq(Lᵢ₊₁) for all consecutive entries (monotonicity)
/// 2. σ'(Lᵢ) = σ(Lᵢ₊₁) (configuration continuity)
/// 3. Γ'(Lᵢ) = Γ(Lᵢ₊₁) (context continuity)
///
/// CAUSALITY \[Lam78\]:
/// For distributed statecharts, entries include causality information
/// to establish happened-before ordering across nodes.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct TransitionLogEntry {
    /// Unique identifier for this log entry
    #[prost(string, tag="1")]
    pub id: ::prost::alloc::string::String,
    /// Timestamp: t ∈ Time
    /// Wall-clock time when this step was executed
    #[prost(message, optional, tag="2")]
    pub timestamp: ::core::option::Option<super::super::google::protobuf::Timestamp>,
    /// Sequence number: seq ∈ ℕ
    /// Monotonically increasing within a machine instance.
    /// Used for ordering and gap detection.
    #[prost(uint64, tag="3")]
    pub sequence: u64,
    /// Triggering event: e ∈ E ∪ {τ}
    /// The event that initiated this step (τ for completion events)
    #[prost(message, optional, tag="4")]
    pub trigger_event: ::core::option::Option<Event>,
    /// Source configuration: σ ∈ P(S)
    /// Active states before transition
    #[prost(message, optional, tag="5")]
    pub source_config: ::core::option::Option<Configuration>,
    /// Target configuration: σ' ∈ P(S)
    /// Active states after transition
    #[prost(message, optional, tag="6")]
    pub target_config: ::core::option::Option<Configuration>,
    /// Fired transitions: T ⊆ δ
    /// Set of transitions that executed in this step
    #[prost(message, repeated, tag="7")]
    pub transitions_fired: ::prost::alloc::vec::Vec<TransitionRef>,
    /// Guard evaluations: G = {(g, result, bindings)}
    /// Results of guard condition evaluation for debugging
    #[prost(message, repeated, tag="8")]
    pub guard_results: ::prost::alloc::vec::Vec<GuardEvaluation>,
    /// Executed actions: A = α₁ · α₂ · ... · αₙ
    /// Sequence of actions executed during this step
    #[prost(message, repeated, tag="9")]
    pub actions_executed: ::prost::alloc::vec::Vec<ActionExecution>,
    /// Context before: Γ
    /// Variable bindings before transition
    #[prost(message, optional, tag="10")]
    pub context_before: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Context after: Γ'
    /// Variable bindings after transition
    #[prost(message, optional, tag="11")]
    pub context_after: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Processing duration: Δt
    /// Time spent executing this step
    #[prost(message, optional, tag="12")]
    pub processing_time: ::core::option::Option<super::super::google::protobuf::Duration>,
    /// Error message if step failed
    #[prost(string, tag="13")]
    pub error: ::prost::alloc::string::String,
    /// Arbitrary metadata (trace IDs, request IDs, etc.)
    #[prost(map="string, string", tag="14")]
    pub metadata: ::std::collections::HashMap<::prost::alloc::string::String, ::prost::alloc::string::String>,
    /// Causality information for distributed ordering \[Lam78\]
    #[prost(message, optional, tag="15")]
    pub causality: ::core::option::Option<CausalityInfo>,
}
/// *
/// TransitionRef is a lightweight reference to a transition.
///
/// FORMAL DEFINITION:
/// A reference r = (label, from, to, event) identifies a transition t ∈ δ
/// without including the full transition definition.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct TransitionRef {
    #[prost(string, tag="1")]
    pub label: ::prost::alloc::string::String,
    #[prost(string, repeated, tag="2")]
    pub from: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    #[prost(string, repeated, tag="3")]
    pub to: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    #[prost(string, tag="4")]
    pub event: ::prost::alloc::string::String,
}
/// *
/// GuardEvaluation records the result of evaluating a guard condition.
///
/// FORMAL DEFINITION \[HN96, Section 4.2\]:
/// Guard evaluation Geval = (expr, result, bindings, error) where:
///    - expr: the guard expression g ∈ G
///    - result: evaluation outcome ∈ {true, false}
///    - bindings: variable values used during evaluation
///    - error: evaluation error if any
///
/// DETERMINISM REQUIREMENT:
/// For reproducible replay, guard evaluation must be deterministic:
///    eval(g, Γ₁) = eval(g, Γ₂) when Γ₁ = Γ₂
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct GuardEvaluation {
    /// Guard expression that was evaluated
    #[prost(string, tag="1")]
    pub guard_expression: ::prost::alloc::string::String,
    /// Evaluation result: true if guard passed
    #[prost(bool, tag="2")]
    pub result: bool,
    /// Variable bindings used during evaluation
    /// Enables debugging of why guard passed/failed
    #[prost(message, optional, tag="3")]
    pub bound_values: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Error message if evaluation failed
    #[prost(string, tag="4")]
    pub error: ::prost::alloc::string::String,
}
/// *
/// ActionExecution records the execution of a single action.
///
/// FORMAL DEFINITION \[HN96, Section 6\]:
/// Action execution Aexec = (name, params, duration, error) where:
///    - name: action identifier
///    - params: action parameters
///    - duration: execution time
///    - error: execution error if any
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ActionExecution {
    #[prost(string, tag="1")]
    pub action_name: ::prost::alloc::string::String,
    #[prost(message, optional, tag="2")]
    pub parameters: ::core::option::Option<super::super::google::protobuf::Struct>,
    #[prost(message, optional, tag="3")]
    pub duration: ::core::option::Option<super::super::google::protobuf::Duration>,
    #[prost(string, tag="4")]
    pub error: ::prost::alloc::string::String,
}
/// *
/// CausalityInfo establishes ordering for distributed statechart execution.
///
/// FORMAL DEFINITION \[Lam78\]:
/// Causality tracking uses logical clocks to establish happened-before (→):
///    - Lamport clock: L(e) ∈ ℕ, monotonic counter
///    - Vector clock: V(e) = (c₁, c₂, ..., cₙ) for n nodes
///
/// ORDERING PROPERTIES:
/// 1. If a → b within same process, then L(a) < L(b)
/// 2. If a is send and b is corresponding receive, then L(a) < L(b)
/// 3. Vector clocks provide exact causality: V(a) < V(b) ⟺ a → b
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct CausalityInfo {
    /// Lamport timestamp: L ∈ ℕ
    /// Simple scalar clock for total ordering
    #[prost(uint64, tag="1")]
    pub lamport_clock: u64,
    /// Vector clock: V = {node_id → counter}
    /// Provides exact causality detection for distributed systems
    #[prost(map="string, uint64", tag="2")]
    pub vector_clock: ::std::collections::HashMap<::prost::alloc::string::String, u64>,
    /// Parent event ID: caused_by
    /// Links this entry to the event that caused it
    #[prost(string, tag="3")]
    pub caused_by: ::prost::alloc::string::String,
    /// Processing node identifier
    /// Which node/partition processed this event
    #[prost(string, tag="4")]
    pub node_id: ::prost::alloc::string::String,
}
