// SECTION 2: EXECUTION TRACES
// ═══════════════════════════════════════════════════════════════════════════

/// *
/// ExecutionTrace represents a complete execution history of a machine instance.
///
/// FORMAL DEFINITION \[HN96, Section 4\]:
/// A trace τ = (id, σ₀, Γ₀, L*, σₙ, Γₙ) where:
///    - id: unique trace identifier
///    - σ₀, Γ₀: initial configuration and context
///    - L* = L₁ · L₂ · ... · Lₙ: sequence of log entries
///    - σₙ, Γₙ: final configuration and context
///
/// WELL-FORMEDNESS CONSTRAINTS:
/// 1. |L*| = n ⟹ seq(Lᵢ) = i for all i ∈ \[1,n\]
/// 2. σ'(Lᵢ) = σ(Lᵢ₊₁) (configuration chain)
/// 3. σ(L₁) = σ₀ and σ'(Lₙ) = σₙ (boundary conditions)
///
/// REPLAY PROPERTY:
/// Given (σ₀, Γ₀) and events(τ), deterministic replay yields identical trace.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ExecutionTrace {
    /// Trace identifier
    #[prost(string, tag="1")]
    pub trace_id: ::prost::alloc::string::String,
    /// Machine instance this trace belongs to
    #[prost(string, tag="2")]
    pub machine_id: ::prost::alloc::string::String,
    /// Chart version being executed
    #[prost(message, optional, tag="3")]
    pub chart_version: ::core::option::Option<ChartVersion>,
    /// Initial configuration: σ₀
    #[prost(message, optional, tag="4")]
    pub initial_config: ::core::option::Option<Configuration>,
    /// Initial context: Γ₀
    #[prost(message, optional, tag="5")]
    pub initial_context: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Log entries: L* = L₁ · L₂ · ... · Lₙ
    #[prost(message, repeated, tag="6")]
    pub entries: ::prost::alloc::vec::Vec<TransitionLogEntry>,
    /// Final configuration: σₙ
    #[prost(message, optional, tag="7")]
    pub final_config: ::core::option::Option<Configuration>,
    /// Final context: Γₙ
    #[prost(message, optional, tag="8")]
    pub final_context: ::core::option::Option<super::super::google::protobuf::Struct>,
    /// Trace metadata
    #[prost(message, optional, tag="9")]
    pub metadata: ::core::option::Option<TraceMetadata>,
}
/// *
/// ChartVersion identifies a specific version of a statechart definition.
///
/// FORMAL DEFINITION:
/// Version V = (semver, hash, parent) where:
///    - semver: human-readable version string
///    - hash: content-addressable hash of chart definition
///    - parent: previous version for lineage
///
/// IDENTITY SEMANTICS:
/// Two charts are identical iff their content hashes match:
///    SC₁ ≡ SC₂ ⟺ hash(SC₁) = hash(SC₂)
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct ChartVersion {
    /// Human-readable version (semver recommended)
    #[prost(string, tag="1")]
    pub version: ::prost::alloc::string::String,
    /// Content-addressable hash: sha256(canonical(SC))
    #[prost(string, tag="2")]
    pub content_hash: ::prost::alloc::string::String,
    /// Creation timestamp
    #[prost(message, optional, tag="3")]
    pub created_at: ::core::option::Option<super::super::google::protobuf::Timestamp>,
    /// Previous version for lineage tracking
    #[prost(string, tag="4")]
    pub previous_version: ::prost::alloc::string::String,
    /// Changelog description
    #[prost(string, tag="5")]
    pub changelog: ::prost::alloc::string::String,
    /// Compatibility classification
    #[prost(enumeration="CompatibilityLevel", tag="6")]
    pub compatibility: i32,
}
/// *
/// TraceMetadata provides summary statistics and sampling information.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct TraceMetadata {
    #[prost(message, optional, tag="1")]
    pub started_at: ::core::option::Option<super::super::google::protobuf::Timestamp>,
    #[prost(message, optional, tag="2")]
    pub ended_at: ::core::option::Option<super::super::google::protobuf::Timestamp>,
    #[prost(uint64, tag="3")]
    pub total_transitions: u64,
    #[prost(uint64, tag="4")]
    pub total_events_processed: u64,
    #[prost(uint64, tag="5")]
    pub total_events_ignored: u64,
    #[prost(string, repeated, tag="6")]
    pub errors: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// Number of machines in aggregate trace
    #[prost(uint64, tag="7")]
    pub machine_count: u64,
    /// Sampling information
    #[prost(message, optional, tag="8")]
    pub sampling: ::core::option::Option<SamplingInfo>,
}
