// ===========================================================================
// SCHEMA EVOLUTION AND MIGRATION
//
// This file defines types for statechart versioning, schema evolution, and
// live migration between chart versions. These capabilities enable continuous
// evolution of statechart-based systems while maintaining operational safety.
//
// THEORETICAL FOUNDATION:
// Schema evolution follows principles from database theory \[BCH+07\] adapted
// for statechart semantics:
//
//    - Compatibility: new version accepts inputs valid for old version
//    - Substitutability: new version preserves observable behavior
//    - Migrability: running instances can be transformed to new version
//
// The migration formalism maps configurations between versions:
//    migrate: Configuration_old × MappingRules → Configuration_new
//
// PRIMARY REFERENCES:
// \[H87\]   D. Harel, "Statecharts: A visual formalism for complex systems,"
//          Science of Computer Programming, vol. 8, no. 3, pp. 231–274, 1987.
//
// \[BCH+07\] P. Buneman et al., "Principles of Database Schema Evolution,"
//           arXiv:0707.4082, 2007.
//
// DESIGN REFERENCE: docs/design/evolution-and-history.md
// ===========================================================================

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 1: CHART DIFFING
// ═══════════════════════════════════════════════════════════════════════════

/// *
/// ChartDiff captures differences between two statechart versions.
///
/// FORMAL DEFINITION:
/// A diff D(SC₁, SC₂) = (V₁, V₂, ΔS, Δδ, ΔE, C, B) where:
///    - V₁, V₂: source and target versions
///    - ΔS: state changes (added, removed, modified)
///    - Δδ: transition changes
///    - ΔE: event changes
///    - C: overall compatibility classification
///    - B: list of breaking changes
///
/// DIFF COMPUTATION:
/// States are matched by label, transitions by (from, to, event) tuple.
/// Changes are classified by their impact on migration requirements.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ChartDiff {
    /// Source version: V₁
    #[prost(message, optional, tag="1")]
    pub from_version: ::core::option::Option<ChartVersion>,
    /// Target version: V₂
    #[prost(message, optional, tag="2")]
    pub to_version: ::core::option::Option<ChartVersion>,
    /// State changes: ΔS = S₂ \ S₁ ∪ S₁ \ S₂ ∪ modified(S₁ ∩ S₂)
    #[prost(message, repeated, tag="3")]
    pub state_changes: ::prost::alloc::vec::Vec<StateDiff>,
    /// Transition changes: Δδ
    #[prost(message, repeated, tag="4")]
    pub transition_changes: ::prost::alloc::vec::Vec<TransitionDiff>,
    /// Event changes: ΔE
    #[prost(message, repeated, tag="5")]
    pub event_changes: ::prost::alloc::vec::Vec<EventDiff>,
    /// Overall compatibility: C = max(severity(B))
    #[prost(enumeration="CompatibilityLevel", tag="6")]
    pub compatibility: i32,
    /// Breaking changes requiring attention
    #[prost(message, repeated, tag="7")]
    pub breaking_changes: ::prost::alloc::vec::Vec<BreakingChange>,
}
/// *
/// StateDiff describes a change to a single state.
///
/// CHANGE SEMANTICS:
///    - ADDED: s ∈ S₂ ∧ s ∉ S₁
///    - REMOVED: s ∈ S₁ ∧ s ∉ S₂
///    - MODIFIED: s ∈ S₁ ∩ S₂ ∧ attrs(s, SC₁) ≠ attrs(s, SC₂)
///    - RENAMED: ∃s₁ ∈ S₁, s₂ ∈ S₂: structure(s₁) ≈ structure(s₂) ∧ label(s₁) ≠ label(s₂)
///    - MOVED: parent(s, SC₁) ≠ parent(s, SC₂)
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct StateDiff {
    #[prost(enumeration="ChangeType", tag="1")]
    pub change_type: i32,
    #[prost(string, tag="2")]
    pub state_label: ::prost::alloc::string::String,
    #[prost(message, optional, tag="3")]
    pub old_state: ::core::option::Option<State>,
    #[prost(message, optional, tag="4")]
    pub new_state: ::core::option::Option<State>,
    #[prost(string, repeated, tag="5")]
    pub modified_fields: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
}
/// *
/// TransitionDiff describes a change to a single transition.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct TransitionDiff {
    #[prost(enumeration="ChangeType", tag="1")]
    pub change_type: i32,
    #[prost(string, tag="2")]
    pub transition_label: ::prost::alloc::string::String,
    #[prost(message, optional, tag="3")]
    pub old_transition: ::core::option::Option<Transition>,
    #[prost(message, optional, tag="4")]
    pub new_transition: ::core::option::Option<Transition>,
    #[prost(string, repeated, tag="5")]
    pub modified_fields: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
}
/// *
/// EventDiff describes a change to an event definition.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct EventDiff {
    #[prost(enumeration="ChangeType", tag="1")]
    pub change_type: i32,
    #[prost(string, tag="2")]
    pub event_name: ::prost::alloc::string::String,
    #[prost(message, optional, tag="3")]
    pub old_event: ::core::option::Option<Event>,
    #[prost(message, optional, tag="4")]
    pub new_event: ::core::option::Option<Event>,
}
/// *
/// BreakingChange identifies a change requiring migration attention.
///
/// BREAKING CHANGE CRITERIA:
/// A change is breaking if it can cause:
///    1. Invalid configuration: σ valid in SC₁ but invalid in SC₂
///    2. Behavioral change: same inputs produce different outputs
///    3. Lost functionality: capabilities in SC₁ unavailable in SC₂
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct BreakingChange {
    #[prost(enumeration="BreakingChangeType", tag="1")]
    pub r#type: i32,
    #[prost(string, tag="2")]
    pub description: ::prost::alloc::string::String,
    #[prost(string, tag="3")]
    pub affected_element: ::prost::alloc::string::String,
    #[prost(enumeration="MigrationRequirement", tag="4")]
    pub migration_required: i32,
}
/// *
/// DeprecationInfo marks elements scheduled for removal.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct DeprecationInfo {
    #[prost(string, tag="1")]
    pub deprecated_in_version: ::prost::alloc::string::String,
    #[prost(string, tag="2")]
    pub removal_version: ::prost::alloc::string::String,
    #[prost(string, tag="3")]
    pub migration_guide: ::prost::alloc::string::String,
    #[prost(string, tag="4")]
    pub replacement: ::prost::alloc::string::String,
}
