// SECTION 2: MIGRATION PLANNING
// ═══════════════════════════════════════════════════════════════════════════

/// *
/// MigrationPlan specifies how to migrate machines between chart versions.
///
/// FORMAL DEFINITION:
/// A migration plan M = (V₁, V₂, strategy, mappings, transform, validations) where:
///    - V₁, V₂: source and target versions
///    - strategy: migration approach (stop-the-world, rolling, etc.)
///    - mappings: state mapping rules
///    - transform: context transformation
///    - validations: post-migration checks
///
/// MIGRATION INVARIANT:
/// For valid migration: ∀ machine m with config σ in V₁:
///    migrate(σ, M) produces valid config σ' in V₂
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct MigrationPlan {
    /// Plan identifier
    #[prost(string, tag="1")]
    pub id: ::prost::alloc::string::String,
    /// Source version: V₁
    #[prost(message, optional, tag="2")]
    pub from_version: ::core::option::Option<ChartVersion>,
    /// Target version: V₂
    #[prost(message, optional, tag="3")]
    pub to_version: ::core::option::Option<ChartVersion>,
    /// Migration strategy
    #[prost(enumeration="MigrationStrategy", tag="4")]
    pub strategy: i32,
    /// State mappings: how to transform configurations
    #[prost(message, repeated, tag="5")]
    pub state_mappings: ::prost::alloc::vec::Vec<StateMapping>,
    /// Transition mappings: for renamed transitions
    #[prost(message, repeated, tag="6")]
    pub transition_mappings: ::prost::alloc::vec::Vec<TransitionMapping>,
    /// Context transformation: how to transform variables
    #[prost(message, optional, tag="7")]
    pub context_transform: ::core::option::Option<ContextTransformation>,
    /// Post-migration validations
    #[prost(message, repeated, tag="8")]
    pub validations: ::prost::alloc::vec::Vec<MigrationValidation>,
    /// Impact assessment
    #[prost(message, optional, tag="9")]
    pub impact: ::core::option::Option<MigrationImpact>,
    /// Dry-run mode: validate without applying
    #[prost(bool, tag="10")]
    pub dry_run: bool,
    /// In-flight transition handling
    #[prost(message, optional, tag="11")]
    pub in_flight_policy: ::core::option::Option<InFlightTransitionPolicy>,
    /// Rollback configuration
    #[prost(message, optional, tag="12")]
    pub rollback_plan: ::core::option::Option<RollbackPlan>,
}
/// *
/// StateMapping defines how to map configurations between versions.
///
/// FORMAL DEFINITION:
/// A state mapping m = (type, from, to, condition, transform) where:
///    - type: mapping strategy
///    - from ⊆ S₁: source states
///    - to ⊆ S₂: target states
///    - condition: optional guard for conditional mapping
///    - transform: context transformation during mapping
///
/// MAPPING SEMANTICS BY TYPE:
///    - IDENTITY: s ∈ σ₁ ⟹ s ∈ σ₂ (label unchanged)
///    - RENAME: s₁ ∈ σ₁ ⟹ s₂ ∈ σ₂ (label changed)
///    - TO_PARENT: s ∈ σ₁ ∧ s removed ⟹ default(parent(s)) ∈ σ₂
///    - SPLIT: s ∈ σ₁ ⟹ f(context) ∈ σ₂ (one-to-many based on condition)
///    - MERGE: {s₁, s₂, ...} ∩ σ₁ ≠ ∅ ⟹ t ∈ σ₂ (many-to-one)
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct StateMapping {
    #[prost(enumeration="StateMappingType", tag="1")]
    pub r#type: i32,
    #[prost(string, repeated, tag="2")]
    pub from_states: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    #[prost(string, repeated, tag="3")]
    pub to_states: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    #[prost(message, optional, tag="4")]
    pub condition: ::core::option::Option<Expression>,
    #[prost(message, optional, tag="5")]
    pub transform: ::core::option::Option<ContextTransformation>,
    #[prost(int32, tag="6")]
    pub priority: i32,
}
/// *
/// TransitionMapping maps transitions between versions.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct TransitionMapping {
    #[prost(string, tag="1")]
    pub from_transition: ::prost::alloc::string::String,
    #[prost(string, tag="2")]
    pub to_transition: ::prost::alloc::string::String,
}
/// *
/// ContextTransformation specifies variable changes during migration.
///
/// TRANSFORM SEMANTICS:
/// Given context Γ, produce Γ' = transform(Γ) by:
///    1. Apply set: Γ'\[k\] = eval(expr, Γ) for each (k, expr) in set
///    2. Apply remove: delete Γ'\[k\] for each k in remove
///    3. Apply rename: Γ'\[new\] = Γ\[old\], delete Γ'\[old\]
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ContextTransformation {
    /// Set variable values: key → CEL expression
    #[prost(map="string, string", tag="1")]
    pub set: ::std::collections::HashMap<::prost::alloc::string::String, ::prost::alloc::string::String>,
    /// Remove variables
    #[prost(string, repeated, tag="2")]
    pub remove: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// Rename variables: old_key → new_key
    #[prost(map="string, string", tag="3")]
    pub rename: ::std::collections::HashMap<::prost::alloc::string::String, ::prost::alloc::string::String>,
}
/// *
/// MigrationValidation defines post-migration checks.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct MigrationValidation {
    #[prost(string, tag="1")]
    pub name: ::prost::alloc::string::String,
    #[prost(string, tag="2")]
    pub expression: ::prost::alloc::string::String,
    #[prost(string, tag="3")]
    pub error_message: ::prost::alloc::string::String,
}
